import importlib.util, pathlib

def link_dir(cfg: dict) -> dict[str, Component]:
    repo: dict[str, Component] = {}
    for path in pathlib.Path(cfg["dir"]).glob("*.py"):
        spec = importlib.util.spec_from_file_location(path.stem, path)
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)                # executes component code
        repo[path.stem] = module.create(**cfg["params"].get(path.stem, {}))
    return repo
